// src/hooks/UseNotifications.js
import { useCallback, useEffect, useState } from 'react';
import { fetchAlerts, fetchAlertDetail, fetchAlertStats } from '../api/NotificationsApi';

export function useNotifications(initial = {}) {
  const [page, setPage] = useState(initial.page ?? 1);
  const [size, setSize] = useState(initial.size ?? 20);
  const [keyword, setKeyword] = useState(initial.keyword ?? '');
  const [level, setLevel] = useState(initial.level ?? 'ALL');
  const [from, setFrom] = useState(initial.from ?? '');
  const [to, setTo] = useState(initial.to ?? '');
  const [sort, setSort] = useState(initial.sort ?? 'collectedAt,desc');

  const [items, setItems] = useState([]);
  const [total, setTotal] = useState(0);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetchAlerts({
        page,
        size,
        keyword,
        level: level === 'ALL' ? '' : level,
        from,
        to,
        sort,
      });
      setItems(res.items || []);
      setTotal(res.total || 0);
    } catch (e) {
      setError(e);
    } finally {
      setLoading(false);
    }
  }, [page, size, keyword, level, from, to, sort]);

  useEffect(() => {
    load();
  }, [load]);

  return {
    notifications: items,
    total,
    loading,
    error,

    page,
    setPage,
    size,
    setSize,
    keyword,
    setKeyword,
    level,
    setLevel,
    from,
    setFrom,
    to,
    setTo,
    sort,
    setSort,

    refresh: load,

    fetchAlertDetail,
    fetchAlertStats,
  };
}
